const { createHmac } = require('crypto');
const path = '/internal/calendar/outbox/claim';
const body = {};
const rawBody = JSON.stringify(body);
const timestamp = String(Math.floor(Date.now() / 1000));
const signedSignature = createHmac('sha256', $env.CALENDAR_INTERNAL_HMAC_KEY).update(`v1\n${timestamp}\nPOST\n${path}\n${rawBody}`).digest('hex');
return [{ json: { signedBody: rawBody, signedTimestamp: timestamp, signedSignature } }];

const { createHmac } = require('crypto');
const path = '/internal/calendar/provider/changes';
const body = { connectionId: $json.provider.connectionId, checkpoint: $json.checkpoint };
const rawBody = JSON.stringify(body);
const timestamp = String(Math.floor(Date.now() / 1000));
const signedSignature = createHmac('sha256', $env.CALENDAR_INTERNAL_HMAC_KEY).update(`v1\n${timestamp}\nPOST\n${path}\n${rawBody}`).digest('hex');
return [{ json: { signedBody: rawBody, signedTimestamp: timestamp, signedSignature } }];

const claimed = $('Claim Calendar Outbox Batch').item.json;
const payload = $json.body ?? $json;
const page = typeof payload === 'string' ? JSON.parse(payload) : payload;
const commands = [];
if (page.resetRequired) commands.push({ operationId: `${claimed.eventId}:reset`, tenantId: claimed.tenantId, ownerId: claimed.ownerId, connectionId: claimed.provider.connectionId, kind: 'sync_token_gone' });
for (const event of (page.events || [])) {
  const base = { operationId: `${claimed.eventId}:event:${event.id}:${event.etag}`, tenantId: claimed.tenantId, ownerId: claimed.ownerId, connectionId: claimed.provider.connectionId, providerEventId: event.id, providerEtag: event.etag };
  if (event.status === 'cancelled') commands.push({ ...base, kind: 'event_deleted' });
  else if (event.start && event.start.dateTime) commands.push({ ...base, kind: 'event_changed', title: event.summary || '', dueAt: event.start.dateTime, timeZone: event.start.timeZone || 'UTC' });
}
const token = page.nextPageToken || page.nextSyncToken;
if (token) commands.push({ operationId: `${claimed.eventId}:checkpoint:${token}`, tenantId: claimed.tenantId, ownerId: claimed.ownerId, connectionId: claimed.provider.connectionId, kind: 'sync_checkpoint', ...(page.nextPageToken ? { nextPageToken: page.nextPageToken } : {}), ...(page.nextSyncToken ? { nextSyncToken: page.nextSyncToken } : {}) });
if (!commands.length) throw new Error('calendar_sync_page_empty');
const batchSize = 250;
const batches = [];
for (let offset = 0; offset < commands.length; offset += batchSize) batches.push(commands.slice(offset, offset + batchSize));
return batches.map((batch) => ({ json: { commands: batch } }));

const { createHmac } = require('crypto');
const path = '/internal/calendar/sync/apply-batch';
const body = { commands: $json.commands };
const rawBody = JSON.stringify(body);
const timestamp = String(Math.floor(Date.now() / 1000));
const signedSignature = createHmac('sha256', $env.CALENDAR_INTERNAL_HMAC_KEY).update(`v1\n${timestamp}\nPOST\n${path}\n${rawBody}`).digest('hex');
return [{ json: { signedBody: rawBody, signedTimestamp: timestamp, signedSignature } }];

const expected = $('Expand Manual Sync Changes').all().length;
const applied = $input.all().length;
if (applied !== expected) throw new Error('calendar_sync_batch_incomplete');
return [{ json: { manualSyncApplied: true } }];

